/** cyrus.my sign-in / sign-up. There is no Cyrus password: both buttons delegate to the one Nxeon identity. */
export async function SignInView({ mode, sp }: { mode: "login" | "create"; sp: Record<string, string | undefined> }) {
  if (!bridgeConfig().enabled || (await headers()).get(CYRUS_HOST_HEADER) !== "1") notFound();
