import type { Metadata } from "next";
import { SEO, type SeoEntry } from "./registry";
import { resolveLivePriceTokens } from "@/lib/seo-prices";
import { fitDescription, fitTitle } from "@/lib/seo-text";

/**
 * Metadata for a new-marketing page, keyed by its PRODUCTION route.
 *
 * - title/description from the SEO registry (seeded from the live site), or
 *   from the page loader's `meta()` when they depend on live data;
 * - canonical = the production route (never the /nxm staging path), so the
 *   staged pages can never compete with the live ones;
 * - OpenGraph/Twitter from the same text (the site-wide opengraph-image
 *   applies unless an image is given);
 * - noindex while the new site is staged; indexable once it replaces the live
 *   routes (NXM_LIVE=1 at launch).
 */
export const NXM_LIVE = process.env.NXM_LIVE === "1";
/** Site-wide card (app/opengraph-image.tsx) for pages without their own art — every page must carry og:image/twitter:image. */
const DEFAULT_OG = "/opengraph-image";

export type SeoOverride = Partial<SeoEntry> & {
  image?: string;
  type?: "website" | "article";
  /** e.g. "/blog?page=3" — defaults to the route */
  canonical?: string;
  /** search results and other thin variants */
  noindex?: boolean;
  article?: { publishedTime?: string; modifiedTime?: string; authors?: string[]; tags?: string[] };
};

export async function nxmMetadata(route: string, over?: SeoOverride): Promise<Metadata> {
  const base = SEO[route];
  if (!base && !over?.title) throw new Error(`nxm SEO: no registry entry for ${route}`);
  const e = { ...base, ...over } as SeoEntry & SeoOverride;
  if (!e.title || !e.description) throw new Error(`nxm SEO: ${route} is missing a title or description`);
  // {price:…} tokens -> live catalogue prices (never a hand-typed figure; see lib/seo-prices.ts)
  e.title = await resolveLivePriceTokens(e.title);
  e.description = await resolveLivePriceTokens(e.description);
  // keep what SERPs show whole: trim trailing clauses/sentences past ~62 / ~158 chars
  e.title = fitTitle(e.title, e.absolute ? "" : " — Nxeon");
  e.description = fitDescription(e.description);
  const title = e.absolute ? { absolute: e.title } : e.title;
  return {
    title,
    description: e.description,
    alternates: { canonical: e.canonical ?? route },
    openGraph: {
      title: e.title,
      description: e.description,
      url: e.canonical ?? route,
      siteName: "Nxeon",
      images: [{ url: e.image ?? DEFAULT_OG }],
      ...(e.type === "article" ? { type: "article" as const, ...(e.article ?? {}) } : { type: "website" as const }),
    },
    twitter: { card: "summary_large_image", title: e.title, description: e.description, images: [e.image ?? DEFAULT_OG] },
    robots: NXM_LIVE && !e.noindex ? { index: true, follow: true } : NXM_LIVE ? { index: false, follow: true } : { index: false, follow: false, nocache: true },
  };
}

/** Breadcrumb trail for a route: every ancestor that has a registry entry. */
export function crumbs(route: string, leafName?: string): { name: string; path: string }[] {
  const out = [{ name: "Home", path: "/" }];
  const parts = route.split("/").filter(Boolean);
  for (let i = 1; i <= parts.length; i++) {
    const path = "/" + parts.slice(0, i).join("/");
    const isLeaf = i === parts.length;
    const name = isLeaf ? (leafName ?? SEO[path]?.crumb) : SEO[path]?.crumb;
    if (name) out.push({ name, path });
  }
  return out;
}
