export const AI_TRAINING_AGENTS = ["GPTBot", "ClaudeBot", "Google-Extended", "Applebot-Extended", "CCBot"];

export type RobotsRule = { userAgent: string | string[]; allow?: string | string[]; disallow?: string | string[] };

export function robotsRules(disallow: string[], env: Record<string, string | undefined> = process.env): RobotsRule[] {
  const training = env.AI_TRAINING_CRAWLERS !== "0";
  return [
    { userAgent: "*", allow: "/", disallow },
    { userAgent: AI_SEARCH_AGENTS, allow: "/", disallow },
    training ? { userAgent: AI_TRAINING_AGENTS, allow: "/", disallow } : { userAgent: AI_TRAINING_AGENTS, disallow: "/" },
