  for (let i = 0; i < urls.length; i += max) out.push(urls.slice(i, i + max));
  return out;
}

export function urlsetXml(origin: string, urls: SitemapUrl[]): string {
  const rows = urls.map((u) => {
    const lm = lastmodDate(u.lastmod);
    return `  <url>\n    <loc>${escapeXml(absUrl(origin, u.path))}</loc>${lm ? `\n    <lastmod>${lm}</lastmod>` : ""}\n  </url>`;
  });
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${rows.join("\n")}\n</urlset>\n`;
}

/** Child sitemap locations are `<origin>/sitemap.xml?page=N` (served by the same route; N is 1-based). */
export function sitemapIndexXml(origin: string, shards: SitemapUrl[][]): string {
  const rows = shards.map((s, i) => {
    const newest = s.map((u) => lastmodDate(u.lastmod)).filter((x): x is string => !!x).sort().pop();
    return `  <sitemap>\n    <loc>${escapeXml(`${trimSlash(origin)}/sitemap.xml?page=${i + 1}`)}</loc>${newest ? `\n    <lastmod>${newest}</lastmod>` : ""}\n  </sitemap>`;
  });
  return `<?xml version="1.0" encoding="UTF-8"?>\n<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${rows.join("\n")}\n</sitemapindex>\n`;
}

/**
 * The sitemap document for `page` (undefined = the main file): the urlset itself while everything fits in one file,
 * otherwise the index; ?page=N is shard N. Returns null for a page that does not exist (the route answers 404).
 */
export function sitemapDocument(origin: string, all: SitemapUrl[], page?: number | null, max = SITEMAP_MAX_URLS): string | null {
  const urls = uniqueUrls(all);
  const shards = shardUrls(urls, max);
  if (page == null) return shards.length <= 1 ? urlsetXml(origin, urls) : sitemapIndexXml(origin, shards);
  if (!Number.isInteger(page) || page < 1 || page > shards.length || shards.length <= 1) return null;
  return urlsetXml(origin, shards[page - 1]);
}

export type CyrusSitemapInput = {
  /** Real last-change date of the landing (release.json builtAt); omitted when unknown. */
  homeLastmod?: Date | null;
  /** [path, DOC.updated] for each legal page. */
  legal: Array<{ path: string; updated: string }>;
  /** cyrus_mods_public_enabled (lib/cyrus-mods/gate.ts) AND CYRUS_SITEMAP_MOD_PAGES=1 (cyrus.my really serves them). */
  modPagesOn: boolean;
  modPages?: Array<{ slug: string; updatedAt: Date }>;
  /** Placeholders for surfaces that do not exist yet; they emit nothing until their own gates are wired. */
  libraryPages?: SitemapUrl[];
  spotlightPages?: SitemapUrl[];
};

/**
 * Indexable URLs of cyrus.my. Not listed on purpose: /status/ (the status page is noindex), /sign-in, /sign-up and
 * every signed-in path (noindex / disallowed). Mod pages appear only when BOTH gates are on.
 */
export function cyrusSitemapUrls(i: CyrusSitemapInput): SitemapUrl[] {
  const urls: SitemapUrl[] = [{ path: "/", lastmod: i.homeLastmod ?? null }];
  for (const l of i.legal) urls.push({ path: l.path, lastmod: parseLegalDate(l.updated) });
  if (i.modPagesOn) {
    for (const m of i.modPages ?? []) if (/^[a-z0-9][a-z0-9-]{0,80}$/.test(m.slug)) urls.push({ path: `/mods/cyrus/${m.slug}`, lastmod: m.updatedAt });
    if ((i.modPages ?? []).length) urls.push({ path: "/mods/cyrus" });
  }
  urls.push(...(i.libraryPages ?? []), ...(i.spotlightPages ?? []));
  return urls;
}

// ---------------------------------------------------------------------------
// Google Search Console verification (owner supplies the token; nothing is verified by us)
// ---------------------------------------------------------------------------
export type GscVerification = { meta: string | null; file: string | null };
/**
 * CYRUS_GSC_VERIFICATION holds EITHER the meta-tag content value (a 20..128 char [A-Za-z0-9_-] token) OR the
 * verification file name Search Console gives you ("google<16 hex>.html", with or without ".html"). Anything else is
 * ignored (it is placed in HTML and in a file name, so it is validated, never escaped-and-trusted).
 */
export function gscVerification(raw: string | null | undefined): GscVerification {
  const v = String(raw ?? "").trim();
  const f = /^(google[0-9a-f]{16})(?:\.html)?$/.exec(v);
  if (f) return { meta: null, file: `${f[1]}.html` };
  if (/^[A-Za-z0-9_-]{20,128}$/.test(v)) return { meta: v, file: null };
  return { meta: null, file: null };
}
export const gscFileBody = (file: string) => `google-site-verification: ${file}\n`;

// ---------------------------------------------------------------------------
// page metadata for app-rendered pages on the Cyrus host
// ---------------------------------------------------------------------------
export function cyrusPageMetadata(o: {
  path: string;
  title?: string;
  description?: string;
  /** false = noindex,nofollow (sign-in, sign-up, beta panel, errors). Default false: opt IN to indexing. */
  index?: boolean;
  env?: Record<string, string | undefined>;
}): Metadata {
  const env = o.env ?? process.env;
  const origin = cyrusSiteOrigin(env);
  const gsc = gscVerification(env.CYRUS_GSC_VERIFICATION);
  const md: Metadata = {
    alternates: { canonical: absUrl(origin, o.path) },
    robots: o.index ? { index: true, follow: true } : { index: false, follow: false },
  };
  if (o.title) md.title = o.title;
  if (o.description) md.description = o.description;
  if (gsc.meta) md.verification = { google: gsc.meta };
  return md;
}

/** nxeon.cloud/cyrus canonicalises to the Cyrus site only when CYRUS_SITE_PRIMARY=1 (off by default). */
export function nxeonCyrusPageCanonical(env: Record<string, string | undefined> = process.env): string | null {
  return env.CYRUS_SITE_PRIMARY === "1" ? `${cyrusSiteOrigin(env)}/` : null;
}
