    description: "Describe a game mod in plain words and Cyrus plans it, writes the code, compiles it, safety-checks it and installs it on your server. Live for Minecraft Java (Paper and Purpur).",
    noindex: !on,
  };
}

export async function load(_p?: Record<string, string>): Promise<NxmLoad> {
  await requireCyrusPageAccess();
