      status: live ? ("live" as const) : ("soon" as const),
      toolchain: g.toolchain, blurb: g.blurb, aliases: g.aliases,
      categories: (s?.categories?.length ? s.categories : g.categories).filter((k) => catBy[k]).slice(0, 4),
      side, sideLabel: side ? SIDE_LABEL[side] : null,

