  it("references the Cyrus sitemap and nothing of Nxeon", () => {
    assert.equal(r.sitemap, `${O}/sitemap.xml`);
    assert.equal(r.host, undefined);
    assert.doesNotMatch(JSON.stringify(r), /nxeon|riddle|chamber/i);
  });
  it("disallows the signed-in app, APIs and parameterised auth URLs, and keeps landing/legal/help/assets files crawlable", () => {
    const d = rules[0].disallow as string[];
    for (const p of ["/new$", "/dashboard", "/account", "/wallet", "/servers", "/api/", "/sign-in?*", "/sign-up?*", "/assets$"]) assert.ok(d.includes(p), p);
    for (const open of ["/", "/legal/terms", "/help", "/assets/css/site.css", "/sign-in", "/status/"]) {
      const hit = d.find((x) => (x.endsWith("$") ? open === x.slice(0, -1) : x.includes("*") ? false : open.startsWith(x)));
      assert.equal(hit, undefined, `${open} must stay crawlable (blocked by ${hit})`);
    }
  });
  it("bot policy is the shared Nxeon policy: search agents allowed, training agents follow AI_TRAINING_CRAWLERS", () => {
    assert.deepEqual(rules[1].userAgent, AI_SEARCH_AGENTS);
    assert.deepEqual(rules[2].userAgent, AI_TRAINING_AGENTS);
    assert.deepEqual(rules[2].allow, "/");
    const off = cyrusRobots({ AI_TRAINING_CRAWLERS: "0" }).rules as typeof rules;
    assert.deepEqual(off[2], { userAgent: AI_TRAINING_AGENTS, disallow: "/" });
    assert.deepEqual(off[1].disallow, CYRUS_DISALLOW);
  });
  it("Nxeon robots.txt is unchanged outside a Cyrus request", async () => {
    const { default: robots } = await import("../app/robots");
    const n = await robots();
    assert.equal(n.sitemap, `${process.env.APP_URL ?? "https://nxeon.cloud"}/sitemap.xml`);
    assert.ok((n.rules as typeof rules)[0].disallow!.includes("/riddle/chamber-of-echoes"));
