describe("cyrus sitemap", () => {
  const legal = [
    { path: "/legal/terms", updated: "September 27, 2026" }, { path: "/legal/privacy", updated: "October 6, 2026" },
    { path: "/legal/aup", updated: "July 23, 2026" }, { path: "/legal/sla", updated: "July 23, 2026" },
