  it("lists home + legal with correct lastmod, absolute https cyrus.my URLs, valid XML", () => {
    const xml = sitemapDocument(O, cyrusSitemapUrls({ homeLastmod: new Date("2026-10-14T10:00:00Z"), legal, modPagesOn: false }))!;
    assert.match(xml, /<urlset xmlns="http:\/\/www\.sitemaps\.org\/schemas\/sitemap\/0\.9">/);
    assert.match(xml, /<loc>https:\/\/cyrus\.my\/<\/loc>\s*<lastmod>2026-10-14<\/lastmod>/);
    assert.match(xml, /<loc>https:\/\/cyrus\.my\/legal\/privacy<\/loc>\s*<lastmod>2026-10-06<\/lastmod>/);
    const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
    assert.equal(locs.length, 5);
    for (const l of locs) assert.match(l, /^https:\/\/cyrus\.my(\/|$)/);
    assert.doesNotMatch(xml, /status|sign-in|sign-up|studio|nxeon/);
  });
  it("omits lastmod instead of inventing one", () => {
    const xml = sitemapDocument(O, cyrusSitemapUrls({ legal: [], modPagesOn: false }))!;
    assert.doesNotMatch(xml, /lastmod/);
    assert.equal(parseLegalDate("not a date"), null);
  });
  it("mod / library / spotlight pages: nothing while off, listed when on", () => {
    const base = { legal: [], modPages: [{ slug: "frost-fox", updatedAt: new Date("2026-10-01T00:00:00Z") }, { slug: "../evil", updatedAt: new Date() }] };
    assert.deepEqual(cyrusSitemapUrls({ ...base, modPagesOn: false }).map((u) => u.path), ["/"]);
    const on = cyrusSitemapUrls({ ...base, modPagesOn: true, libraryPages: [{ path: "/library/x" }], spotlightPages: [{ path: "/spotlight/y" }] }).map((u) => u.path);
    assert.deepEqual(on, ["/", "/mods/cyrus/frost-fox", "/mods/cyrus", "/library/x", "/spotlight/y"]);
  });
  it("escapes XML and normalises paths", () => {
    assert.equal(escapeXml(`a&b<c>"d'`), "a&amp;b&lt;c&gt;&quot;d&apos;");
    assert.match(urlsetXml(O, [{ path: "/x?a=1&b=2" }]), /<loc>https:\/\/cyrus\.my\/x\?a=1&amp;b=2<\/loc>/);
    assert.equal(absUrl(O + "/", "/legal/terms/"), `${O}/legal/terms`);
    assert.equal(absUrl(O, "/"), `${O}/`);
    assert.equal(cyrusSiteOrigin({ CYRUS_ORIGIN: "http://cyrus.my/" }), O);
    assert.equal(cyrusSiteOrigin({ CYRUS_HOSTS: "www.cyrus.my,cyrus.my" }), O);
  });
  it("shards past the URL limit into an index + ?page=N files", () => {
    const many = Array.from({ length: 7 }, (_, i) => ({ path: `/mods/cyrus/m${i}`, lastmod: `2026-10-0${i + 1}` }));
    assert.equal(shardUrls(many, 3).length, 3);
    const idx = sitemapDocument(O, many, null, 3)!;
    assert.match(idx, /<sitemapindex/);
    assert.match(idx, /<loc>https:\/\/cyrus\.my\/sitemap\.xml\?page=3<\/loc>\s*<lastmod>2026-10-07<\/lastmod>/);
    assert.match(sitemapDocument(O, many, 2, 3)!, /m3<\/loc>[\s\S]*m5<\/loc>/);
    assert.equal(sitemapDocument(O, many, 4, 3), null);
    assert.equal(sitemapDocument(O, many, 0, 3), null);
    assert.equal(sitemapDocument(O, many.slice(0, 2), 1, 3), null, "a single-file sitemap has no pages");
    assert.match(sitemapIndexXml(O, [many]), /sitemap\.xml\?page=1/);
  });
});

