import { AI_SEARCH_AGENTS, AI_TRAINING_AGENTS, robotsRules } from "../lib/seo-robots-policy";
import { bridgeConfig } from "../lib/cyrus/bridge/config";
import { cyrusHostRoute } from "../lib/cyrus/bridge/routing";
import { middleware } from "../middleware";

const read = (p: string) => readFileSync(p, "utf8");
const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1" });
const O = "https://cyrus.my";

describe("cyrus robots.txt", () => {
  const r = cyrusRobots({});
  const rules = r.rules as Array<{ userAgent: string | string[]; allow?: string | string[]; disallow?: string | string[] }>;
  it("references the Cyrus sitemap and nothing of Nxeon", () => {
    assert.equal(r.sitemap, `${O}/sitemap.xml`);
    assert.equal(r.host, undefined);
    assert.doesNotMatch(JSON.stringify(r), /nxeon|riddle|chamber/i);
  });
  it("disallows the signed-in app, APIs and parameterised auth URLs, and keeps landing/legal/help/assets files crawlable", () => {
    const d = rules[0].disallow as string[];
    for (const p of ["/new$", "/dashboard", "/account", "/wallet", "/servers", "/api/", "/sign-in?*", "/sign-up?*", "/assets$"]) assert.ok(d.includes(p), p);
    for (const open of ["/", "/legal/terms", "/help", "/assets/css/site.css", "/sign-in", "/status/"]) {
      const hit = d.find((x) => (x.endsWith("$") ? open === x.slice(0, -1) : x.includes("*") ? false : open.startsWith(x)));
      assert.equal(hit, undefined, `${open} must stay crawlable (blocked by ${hit})`);
    }
  });
  it("bot policy is the shared Nxeon policy: search agents allowed, training agents follow AI_TRAINING_CRAWLERS", () => {
    assert.deepEqual(rules[1].userAgent, AI_SEARCH_AGENTS);
    assert.deepEqual(rules[2].userAgent, AI_TRAINING_AGENTS);
    assert.deepEqual(rules[2].allow, "/");
    const off = cyrusRobots({ AI_TRAINING_CRAWLERS: "0" }).rules as typeof rules;
    assert.deepEqual(off[2], { userAgent: AI_TRAINING_AGENTS, disallow: "/" });
    assert.deepEqual(off[1].disallow, CYRUS_DISALLOW);
  });
  it("Nxeon robots.txt is unchanged outside a Cyrus request", async () => {
    const { default: robots } = await import("../app/robots");
    const n = await robots();
    assert.equal(n.sitemap, `${process.env.APP_URL ?? "https://nxeon.cloud"}/sitemap.xml`);
    assert.ok((n.rules as typeof rules)[0].disallow!.includes("/riddle/chamber-of-echoes"));
    assert.deepEqual(n.rules, robotsRules(["/dashboard", "/admin", "/api", "/login", "/register", "/forgot-password", "/reset-password", "/riddle/chamber-of-echoes"]));
  });
});

describe("cyrus sitemap", () => {
  const legal = [
    { path: "/legal/terms", updated: "September 27, 2026" }, { path: "/legal/privacy", updated: "October 6, 2026" },
    { path: "/legal/aup", updated: "July 23, 2026" }, { path: "/legal/sla", updated: "July 23, 2026" },
  ];
  it("lists home + legal with correct lastmod, absolute https cyrus.my URLs, valid XML", () => {
    const xml = sitemapDocument(O, cyrusSitemapUrls({ homeLastmod: new Date("2026-10-14T10:00:00Z"), legal, modPagesOn: false }))!;
    assert.match(xml, /<urlset xmlns="http:\/\/www\.sitemaps\.org\/schemas\/sitemap\/0\.9">/);
    assert.match(xml, /<loc>https:\/\/cyrus\.my\/<\/loc>\s*<lastmod>2026-10-14<\/lastmod>/);
    assert.match(xml, /<loc>https:\/\/cyrus\.my\/legal\/privacy<\/loc>\s*<lastmod>2026-10-06<\/lastmod>/);
    const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1]);
    assert.equal(locs.length, 5);
    for (const l of locs) assert.match(l, /^https:\/\/cyrus\.my(\/|$)/);
    assert.doesNotMatch(xml, /status|sign-in|sign-up|studio|nxeon/);
  });
  it("omits lastmod instead of inventing one", () => {
    const xml = sitemapDocument(O, cyrusSitemapUrls({ legal: [], modPagesOn: false }))!;
    assert.doesNotMatch(xml, /lastmod/);
    assert.equal(parseLegalDate("not a date"), null);
  });
  it("mod / library / spotlight pages: nothing while off, listed when on", () => {
    const base = { legal: [], modPages: [{ slug: "frost-fox", updatedAt: new Date("2026-10-01T00:00:00Z") }, { slug: "../evil", updatedAt: new Date() }] };
    assert.deepEqual(cyrusSitemapUrls({ ...base, modPagesOn: false }).map((u) => u.path), ["/"]);
    const on = cyrusSitemapUrls({ ...base, modPagesOn: true, libraryPages: [{ path: "/library/x" }], spotlightPages: [{ path: "/spotlight/y" }] }).map((u) => u.path);
    assert.deepEqual(on, ["/", "/mods/cyrus/frost-fox", "/mods/cyrus", "/library/x", "/spotlight/y"]);
  });
  it("escapes XML and normalises paths", () => {
    assert.equal(escapeXml(`a&b<c>"d'`), "a&amp;b&lt;c&gt;&quot;d&apos;");
    assert.match(urlsetXml(O, [{ path: "/x?a=1&b=2" }]), /<loc>https:\/\/cyrus\.my\/x\?a=1&amp;b=2<\/loc>/);
    assert.equal(absUrl(O + "/", "/legal/terms/"), `${O}/legal/terms`);
    assert.equal(absUrl(O, "/"), `${O}/`);
    assert.equal(cyrusSiteOrigin({ CYRUS_ORIGIN: "http://cyrus.my/" }), O);
    assert.equal(cyrusSiteOrigin({ CYRUS_HOSTS: "www.cyrus.my,cyrus.my" }), O);
  });
  it("shards past the URL limit into an index + ?page=N files", () => {
    const many = Array.from({ length: 7 }, (_, i) => ({ path: `/mods/cyrus/m${i}`, lastmod: `2026-10-0${i + 1}` }));
    assert.equal(shardUrls(many, 3).length, 3);
    const idx = sitemapDocument(O, many, null, 3)!;
    assert.match(idx, /<sitemapindex/);
    assert.match(idx, /<loc>https:\/\/cyrus\.my\/sitemap\.xml\?page=3<\/loc>\s*<lastmod>2026-10-07<\/lastmod>/);
    assert.match(sitemapDocument(O, many, 2, 3)!, /m3<\/loc>[\s\S]*m5<\/loc>/);
    assert.equal(sitemapDocument(O, many, 4, 3), null);
    assert.equal(sitemapDocument(O, many, 0, 3), null);
    assert.equal(sitemapDocument(O, many.slice(0, 2), 1, 3), null, "a single-file sitemap has no pages");
    assert.match(sitemapIndexXml(O, [many]), /sitemap\.xml\?page=1/);
  });
});

describe("cyrus host routing + headers", () => {
  const route = (p: string, m = "GET") => cyrusHostRoute({ pathname: p, search: "", method: m, cfg });
  it("robots.txt and sitemap.xml reach the app on the Cyrus host (GET/HEAD only)", () => {
    assert.deepEqual(route("/sitemap.xml"), { kind: "pass" });
    assert.deepEqual(route("/robots.txt"), { kind: "pass" });
    assert.equal(route("/sitemap.xml", "POST").kind, "notfound");
    assert.equal(route("/sitemap-index.xml").kind, "notfound");
  });
  it("X-Robots-Tag: noindex on app/auth paths, none on public ones", () => {
    for (const p of ["/sign-in", "/sign-up", "/auth/nxeon/start", "/studio", "/studio/x", "/new", "/home", "/account", "/wallet", "/servers", "/projects/abc", "/assets", "/api/cyrus/health", "/dashboard/cyrus"])
      assert.equal(cyrusXRobotsTag(p), "noindex, nofollow", p);
    for (const p of ["/", "/legal/terms", "/legal", "/help", "/plans", "/assets/css/site.css", "/sitemap.xml", "/robots.txt", "/newsletter"])
      assert.equal(cyrusXRobotsTag(p), null, p);
  });
  const prev = { ...process.env };
  const mw = (url: string, host: string) => middleware(new NextRequest(url, { headers: { host } }));
  it("middleware stamps the header on the Cyrus host only", () => {
    Object.assign(process.env, { CYRUS_DOMAIN_MODE: "1", CYRUS_HOSTS: "cyrus.my,www.cyrus.my" });
    try {
      assert.equal(mw("https://cyrus.my/sign-in?next=%2Fnew", "cyrus.my").headers.get("x-robots-tag"), "noindex, nofollow");
      assert.equal(mw("https://cyrus.my/login", "cyrus.my").headers.get("x-robots-tag"), "noindex, nofollow", "redirects carry it too");
      assert.equal(mw("https://cyrus.my/legal/terms", "cyrus.my").headers.get("x-robots-tag"), null);
      assert.equal(mw("https://cyrus.my/sitemap.xml", "cyrus.my").headers.get("x-robots-tag"), null);
      assert.equal(mw("https://nxeon.cloud/sign-in", "nxeon.cloud").headers.get("x-robots-tag"), null);
    } finally {
      for (const k of ["CYRUS_DOMAIN_MODE", "CYRUS_HOSTS"]) { if (prev[k] === undefined) delete process.env[k]; else process.env[k] = prev[k]; }
    }
  });
});

describe("Search Console verification + page metadata", () => {
  it("accepts a meta token or a google<hex>.html name, nothing else", () => {
    assert.deepEqual(gscVerification("abcDEF123_-abcDEF123_-xyz"), { meta: "abcDEF123_-abcDEF123_-xyz", file: null });
    assert.deepEqual(gscVerification("google0123456789abcdef.html"), { meta: null, file: "google0123456789abcdef.html" });
    assert.deepEqual(gscVerification("google0123456789abcdef"), { meta: null, file: "google0123456789abcdef.html" });
    for (const bad of ["", undefined, "short", `"><script>`, "google123.html", "../google0123456789abcdef.html", "a".repeat(129)])
      assert.deepEqual(gscVerification(bad), { meta: null, file: null }, String(bad));
    assert.equal(gscFileBody("google0123456789abcdef.html"), "google-site-verification: google0123456789abcdef.html\n");
  });
  it("indexable pages get a cyrus.my canonical; noindex pages get none; the token is emitted when set", () => {
    const legal = cyrusPageMetadata({ path: "/legal/terms", index: true, env: { CYRUS_GSC_VERIFICATION: "abcDEF123_-abcDEF123_-xyz" } });
    assert.equal(legal.alternates?.canonical, `${O}/legal/terms`);
    assert.deepEqual(legal.robots, { index: true, follow: true });
    assert.deepEqual(legal.verification, { google: "abcDEF123_-abcDEF123_-xyz" });
    const si = cyrusPageMetadata({ path: "/sign-in", title: "Sign in to Cyrus", env: {} });
    assert.equal(si.alternates, undefined);
    assert.deepEqual(si.robots, { index: false, follow: false });
    assert.equal(si.verification, undefined);
  });
  it("nxeon.cloud/cyrus canonicalises to cyrus.my only behind CYRUS_SITE_PRIMARY=1", () => {
    assert.equal(nxeonCyrusPageCanonical({}), null);
    assert.equal(nxeonCyrusPageCanonical({ CYRUS_SITE_PRIMARY: "1" }), `${O}/`);
  });
  it("the Cyrus-host legal/auth pages use these helpers (no nxeon.cloud canonical)", () => {
    for (const d of ["terms", "privacy", "aup", "sla"]) assert.match(read(`app/cyrus-host/legal/${d}/page.tsx`), new RegExp(`cyrusPageMetadata\\(\\{ path: "/legal/${d}", index: true`));
    for (const d of ["sign-in", "sign-up"]) assert.match(read(`app/cyrus-host/${d}/page.tsx`), /index: false/);
  });
});

describe("landing head (publish.sh check)", () => {
  const html = read("apps/cyrus-site/src/index.html");
  it("has lang, canonical, OG/Twitter, 1200x630 image, JSON-LD, one h1, nothing invented", () => {
    assert.match(html, /<html lang="en">/);
    assert.match(html, /<link rel="canonical" href="https:\/\/cyrus\.my\/">/);
    assert.equal((html.match(/<h1[\s>]/g) ?? []).length, 1);
    const ld = JSON.parse(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/.exec(html)![1]);
    const types = ld["@graph"].map((n: { "@type": string }) => n["@type"]);
    assert.deepEqual(types, ["Organization", "WebSite", "SoftwareApplication"]);
    assert.doesNotMatch(JSON.stringify(ld), /aggregateRating|review|offers|price/i, "no fake ratings or prices");
    assert.match(JSON.stringify(ld), /Private beta/);
    for (const t of html.match(/<img\b[^>]*>/g)!) assert.match(t, /\balt="/), assert.match(t, /\bwidth="\d+"/), assert.match(t, /\bheight="\d+"/);
  });
  it("og image exists and is 1200x630", () => {
    const b = readFileSync("apps/cyrus-site/src/assets/og/cyrus-og-1200x630.jpg");
    let i = 2, w = 0, h = 0;
    while (i < b.length) { if (b[i] !== 0xff) { i++; continue; } const m = b[i + 1]; if (m >= 0xc0 && m <= 0xc3) { h = b.readUInt16BE(i + 5); w = b.readUInt16BE(i + 7); break; } i += 2 + b.readUInt16BE(i + 2); }
    assert.deepEqual([w, h], [1200, 630]);
  });
  it("publish.sh check passes on the real source and FAILS when canonical / OG / JSON-LD is missing", () => {
    execFileSync("bash", ["apps/cyrus-site/publish.sh", "check"], { encoding: "utf8" });
    const tmp = mkdtempSync(path.join(os.tmpdir(), "cyrus-seo-"));
    try {
      const broken: Array<[string, RegExp, string]> = [
        ["canonical", /<link rel="canonical"[^>]*>\n/, "seo: canonical"],
        ["og", /<meta property="og:image" [^>]*>\n/, "seo: og:image missing"],
        ["jsonld", /<script type="application\/ld\+json">[\s\S]*?<\/script>\n/, "seo: JSON-LD missing"],
      ];
      for (const [name, re, want] of broken) {
        const dir = path.join(tmp, name);
        cpSync("apps/cyrus-site/src", dir, { recursive: true });
        writeFileSync(path.join(dir, "index.html"), html.replace(re, ""));
        const r = spawnSync("bash", ["apps/cyrus-site/publish.sh", "check"], { encoding: "utf8", env: { ...process.env, CYRUS_SITE_SRC: dir } });
        assert.notEqual(r.status, 0, `${name} removal must fail the check`);
        assert.ok((r.stdout + r.stderr).includes(want), `${name}: ${r.stdout}${r.stderr}`);
      }
    } finally { rmSync(tmp, { recursive: true, force: true }); }
  });
  it("build injects the GSC meta token / writes the verification file, and rejects junk", () => {
    const run = (v: string) => spawnSync("bash", ["apps/cyrus-site/publish.sh", "build"], { encoding: "utf8", env: { ...process.env, CYRUS_GSC_VERIFICATION: v } });
    try {
      assert.equal(run("abcDEF123_-abcDEF123_-xyz").status, 0);
      assert.match(read("apps/cyrus-site/dist/index.html"), /<meta name="google-site-verification" content="abcDEF123_-abcDEF123_-xyz">/);
      assert.equal(run("google0123456789abcdef.html").status, 0);
      assert.equal(read("apps/cyrus-site/dist/google0123456789abcdef.html"), "google-site-verification: google0123456789abcdef.html\n");
      assert.doesNotMatch(read("apps/cyrus-site/dist/index.html"), /google-site-verification" content/);
      assert.notEqual(run('"><script>alert(1)</script>').status, 0);
      assert.equal(spawnSync("bash", ["apps/cyrus-site/publish.sh", "build"], { encoding: "utf8", env: { ...process.env, CYRUS_GSC_VERIFICATION: "" } }).status, 0);
      assert.doesNotMatch(read("apps/cyrus-site/dist/index.html"), /google-site-verification" content/);
    } finally { rmSync("apps/cyrus-site/dist", { recursive: true, force: true }); }
  });
});

describe("nginx vhost + matrix script", () => {
  const conf = read("deploy/cyrus/nginx-cyrus-my.conf");
  it("proxies robots.txt and sitemap.xml to the app and serves only the Search Console file shape statically", () => {
    assert.match(conf, /location ~ \^\/\(favicon\\\.ico\|robots\\\.txt\|sitemap\\\.xml\|/);
    assert.match(conf, /location ~ \^\/google\[0-9a-f\]\{16\}\\\.html\$ \{ try_files \$uri =404;/);
  });
  it("the matrix script checks the content of both files and the verification path", () => {
    const sh = read("scripts/cyrus/nginx-cyrus-my-check.sh");
    assert.match(sh, /sitemap: https:\/\/cyrus\.my\/sitemap\.xml/);
    assert.match(sh, /<loc>https:\/\/cyrus\.my\//);
    assert.match(sh, /probe miss \/google0123456789abcdef\.html/);
  });
});
